import{_ as p,a0 as u,w as i,s as a,ao as l,I as n,x as e,a1 as s,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"当今世界的开源安全问题 | LCTT x X-CMD","titleTemplate":false,"description":"当今世界的开源安全问题 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"当今世界的开源安全问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"当今世界的开源安全问题 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221004 Security Issues With Open Source In Today-s World","title":"当今世界的开源安全问题","tag":"202210","desc":""},"relativePath":"202210/20221004 Security Issues With Open Source In Today-s World.md","filePath":"[post].md"}'),d={name:"202210/20221004 Security Issues With Open Source In Today-s World.md"};function m(f,t,T,x,w,y){const o=u("Link");return i(),a("div",null,[t[15]||(t[15]=l('<h1 id="当今世界的开源安全问题" tabindex="-1">当今世界的开源安全问题 <a class="header-anchor" href="#当今世界的开源安全问题" aria-label="Permalink to “当今世界的开源安全问题”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/10/160918vmfxmsm4bnwi0nb4.jpg" alt=""></p><blockquote><p>开源代码可能是当今大多数公司最可行的选择，但它也伴随着自己的问题。</p></blockquote><p>许多人支持使用 <ruby>开源软件<rt>open source software</rt></ruby>（OSS）。毕竟，我们为什么要不断地尝试构建代码来解决别人已经解决过的问题？为什么不分享信息并逐步和迭代地增强当前的开源解决方案呢？这些<ruby>平等主义价值观<rt>egalitarian values</rt></ruby>，可能是整个文明的根本，更不用说软件了，但还是包含了几千年来一直存在的冲突。</p><p>开源软件安全的问题在于，尽管任何人都可以查看源代码，但这并不意味着他们会这么做。有一些广泛使用的开源项目仅由数量有限的工程师维护。这些工程师无法完全自愿地提供时间和精力，因为他们也需要支付他们的账单。</p><p>即使对于更复杂的开源项目，这也是一个问题。举个例子，Linux 内核项目由 3000 多万行代码组成，包含数百个需要解决的缺陷，并有近 2000 名活跃的开发者。每个活跃的开发者都写了超过 15000 行的代码。</p><p>根据 Linux 基金会最近的一项研究，一个应用程序平均有 5.1 个重大漏洞仍未解决，41% 的企业对其开源软件的安全性缺乏信心。而更糟糕的是，只有 49% 的企业拥有开源安全策略。</p><p>即使开源软件有安全漏洞，这也不能保证它能被修复。调查显示，目前修复一个漏洞平均需要 97.8 天，使使用该软件的企业在几个月内容易受到攻击。这就是开源软件安全有时被忽视的地方：就像好人可以寻找代码中的错误和漏洞来修复它们一样，坏人也可以寻找同样的漏洞来利用它们。</p><p>仅仅依靠志愿者社区来发现漏洞、报告漏洞和修复漏洞是一个漫长的过程。在你继续受益于开源的广泛优势的同时，花钱请人检查你的开源解决方案的安全性可以帮助弥补这个问题。</p><p>由于必须部署开源软件的更新和补丁以保证系统的安全，这一要求会带来独特的困难。如果你的解决方案依赖于某个软件版本，更新你的关键任务软件可能会导致功能损失和/或计划外的停机。当情况对业务至关重要时，聘请专家来回传补丁并维护一个时间更长的版本可能比让大型社区愿意去做更加优雅。</p><p>开源社区经常使用的一句话是：“这是开源的，去改变它吧！”它强调了一个关键点：当别人在项目中投入时间、精力或金钱的时候，期望白白得到良好的安全水平是不合理的，也是不可持续的。</p><p>要么按原定计划为开源做出贡献，改进代码并为他人发布，要么聘请专业人士管理开源代码并在必要时进行调试，这些都是选择。然而，这个行业无法承担完全不做贡献。</p><hr>',13)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),s(o,{href:"https://www.opensourceforu.com/2022/10/security-issues-with-open-source-in-todays-world/"},{default:r(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/10/security-issues-with-open-source-in-todays-world/",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=e("作者：",-1)),s(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:r(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),s(o,{href:"https://github.com/lkxed"},{default:r(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),s(o,{href:"https://github.com/KevinZonda"},{default:r(()=>[...t[4]||(t[4]=[e("KevinZonda",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),s(o,{href:"https://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const g=p(d,[["render",m]]);export{b as __pageData,g as default};
